      $C1 ≡ Functor_cart_cat (@fapp0 $K Cat_cat $D $x) (@fapp0 $K Cat_cat $D $y);
      $C2 ≡ Functor_cart_cat (@fapp0 $K Cat_cat $E $x) (@fapp0 $K Cat_cat $D $y);
      $P ≡ @hom_precomp_along_func Cat_cat Cat_cat (@id_func Cat_cat)
        (@fapp0 $K Cat_cat $D $y) (@fapp0 $K Cat_cat $E $x) (@fapp0 $K Cat_cat $D $x)
        (@tapp0_fapp0 $K Cat_cat $E $D $x $FF);
      $H ≡ @fapp1_func $K Cat_cat $D $x $y ];
